import{_ as r,o as t,c as s,a5 as a}from"./chunks/framework.CslsFoWx.js";const o="/VendoraSystem-docs/captures/2026-11-08-captures-stock-caisse/01-01-bons-attendus.webp",n="/VendoraSystem-docs/captures/2026-11-08-captures-stock-caisse/02-02-controle.webp",i="/VendoraSystem-docs/captures/2026-11-08-captures-stock-caisse/03-03-reception-enregistree.webp",c="/VendoraSystem-docs/captures/2026-11-08-captures-stock-caisse/04-01-transferts-a-recevoir.webp",d="/VendoraSystem-docs/captures/2026-11-08-captures-stock-caisse/05-02-compter-et-motiver.webp",u="/VendoraSystem-docs/captures/2026-11-08-captures-stock-caisse/06-03-transfert-recu.webp",l="/VendoraSystem-docs/captures/2026-11-08-captures-stock-caisse/07-01-alertes.webp",p="/VendoraSystem-docs/captures/2026-11-08-captures-stock-caisse/android-01-bons-attendus.webp",m="/VendoraSystem-docs/captures/2026-11-08-captures-stock-caisse/android-02-controle.webp",g="/VendoraSystem-docs/captures/2026-11-08-captures-stock-caisse/android-03-reception-enregistree.webp",f="/VendoraSystem-docs/captures/2026-11-08-captures-stock-caisse/android-04-transferts-a-recevoir.webp",h="/VendoraSystem-docs/captures/2026-11-08-captures-stock-caisse/android-05-compter-et-motiver.webp",b="/VendoraSystem-docs/captures/2026-11-08-captures-stock-caisse/android-06-transfert-recu.webp",v="/VendoraSystem-docs/captures/2026-11-08-captures-stock-caisse/android-07-alertes.webp",C=JSON.parse('{"title":"Captures réception fournisseur, transferts et alertes sur la caisse (08/11/2026)","description":"","frontmatter":{},"headers":[],"relativePath":"preuves/2026-11-08-captures-stock-caisse.md","filePath":"generated/preuves/2026-11-08-captures-stock-caisse.md","lastUpdated":null}'),_={name:"preuves/2026-11-08-captures-stock-caisse.md"};function k(T,e,q,P,y,S){return t(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="captures-reception-fournisseur-transferts-et-alertes-sur-la-caisse-08-11-2026" tabindex="-1">Captures réception fournisseur, transferts et alertes sur la caisse (08/11/2026) <a class="header-anchor" href="#captures-reception-fournisseur-transferts-et-alertes-sur-la-caisse-08-11-2026" aria-label="Permalink to &quot;Captures réception fournisseur, transferts et alertes sur la caisse (08/11/2026)&quot;">​</a></h1><p class="muted">Dossier <code>docs/captures/2026-11-08-captures-stock-caisse</code> · 0 image(s) · 0 trace(s)</p><div><p>Carte Trello « Captures réception fournisseur, transferts et alertes ». Les pages HM-19 (<a href="./../../../help/guide/appareil-caisse/reception-sur-la-caisse">réception sur la caisse</a>), HM-20 (<a href="./../../../help/guide/appareil-caisse/recevoir-un-transfert">recevoir un transfert</a>) et HM-22 (<a href="./../../../help/guide/appareil-caisse/alertes-responsable">alertes du responsable</a>) n&#39;avaient aucune capture faute de données. Elles sont maintenant illustrées (FR, EN, AR), sur iPad (caisse iOS appairée au magasin principal de « Épicerie Lumière (démo) », connexion de « Marc (responsable) »).</p><h2 id="donnees-de-demo" tabindex="-1">Données de démo <a class="header-anchor" href="#donnees-de-demo" aria-label="Permalink to &quot;Données de démo&quot;">​</a></h2><p>Nouveau script <code>help/tools/seed/seed-stock-caisse.py</code> (après <code>seed-demo.py --retail</code>, mêmes options), par l&#39;API publique, sur le commerce fictif « Épicerie Lumière (démo) » :</p><ul><li>responsable <strong>Marc (responsable)</strong> (MANAGER, PIN aléatoire dans le fichier de secrets hors dépôt) ;</li><li>second magasin <strong>Épicerie Lumière — Halles (démo)</strong>, approvisionné par une réception de « Ferme des Collines (démo) » ;</li><li>transfert <strong>TR-2026-0001</strong> poussé et expédié des Halles vers le magasin principal (chocolat 12, jus d&#39;orange 10, beurre 6) ;</li><li>bon de commande <strong>PO-EPI-2026-0001</strong> envoyé (yaourts 24, beurre 12, cidre 6, eau gazeuse 24) ;</li><li>seuil de stock bas à 30 sur « Yaourt nature x4 » et « Eau gazeuse 1 L » (24 en stock) → alertes des responsables.</li></ul><p>Le compte en essai (formule Commerce : 1 magasin) a reçu une dérogation « EXTRA_STORES = 1 » par la console (compte d&#39;équipe de test local) pour créer le second magasin.</p><h2 id="captures" tabindex="-1">Captures <a class="header-anchor" href="#captures" aria-label="Permalink to &quot;Captures&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capture</th><th>Ce qu&#39;elle montre</th></tr></thead><tbody><tr><td><img src="'+o+'" alt=""></td><td>Réceptions fournisseur : le bon envoyé, 4 lignes attendues</td></tr><tr><td><img src="'+n+'" alt=""></td><td>Contrôle : commandé / déjà reçu / attendu, quantité reçue, cidre 4 sur 6 → écart « Manquant », <strong>Tout reçu</strong>, <strong>Valider la réception</strong></td></tr><tr><td><img src="'+i+'" alt=""></td><td>« Réception de PO-EPI-2026-0001 enregistrée : stock à jour — commande soldée » (seconde réception du reliquat)</td></tr><tr><td><img src="'+c+'" alt=""></td><td>Transferts à recevoir : TR-2026-0001 des Halles (nom de l&#39;expéditeur flouté)</td></tr><tr><td><img src="'+d+'" alt=""></td><td>Comptage +/− (beurre 5 sur 6), motif « Casse à la livraison », PIN du responsable (masqué)</td></tr><tr><td><img src="'+u+'" alt=""></td><td>« Transfert TR-2026-0001 reçu : stock du magasin à jour, 1 écart(s) motivé(s) »</td></tr><tr><td><img src="'+l+'" alt=""></td><td>Alertes : chiffres du jour, deux « Stock bas », « Transfert à réceptionner »</td></tr></tbody></table><p>Scénarios : <code>help/tools/mobile/scenarios/appareil-caisse-{reception-sur-la-caisse,recevoir-un-transfert,alertes-responsable}-ios.json</code>.</p><h2 id="defauts-releves-pendant-la-seance-non-corriges-ici" tabindex="-1">Défauts relevés pendant la séance (non corrigés ici) <a class="header-anchor" href="#defauts-releves-pendant-la-seance-non-corriges-ici" aria-label="Permalink to &quot;Défauts relevés pendant la séance (non corrigés ici)&quot;">​</a></h2><ul><li><strong>iOS — plantage à la validation d&#39;une réception fournisseur</strong> quand le champ « Reçu » d&#39;une ligne a encore le focus (quantité saisie au clavier puis <strong>Valider la réception</strong> directement) : <code>ReceptionModel.valider()</code> vide <code>lignes</code> alors que le <code>TextField</code> lié par <code>ForEach($modele.lignes)</code> (<code>iosApp/PosApp/Achats/ReceptionView.swift</code>) termine son édition → <code>Array</code> hors bornes dans <code>PlatformTextFieldCoordinator.textFieldDidEndEditing</code> (<code>EXC_BREAKPOINT</code>, rapport <code>PosApp-2026-11-08-205518.ips</code>). La réception, enregistrée juste avant, est bien synchronisée au redémarrage (bon passé en « Reçu en partie »). Contournement pour la capture : masquer le clavier avant de valider. Correctif à faire (retirer le focus avant de vider la liste, ou lier par identifiant) + parité Android à vérifier.</li><li>La liste des transferts affiche « expédié par » + l&#39;identifiant du compte (partie locale de l&#39;email) quand le propriétaire n&#39;a pas de nom affiché.</li><li>Les alertes « Stock bas » gardent le stock du moment de l&#39;alerte (24) même après la réception (lecture seule, historique : comportement attendu, à préciser dans la page si besoin).</li></ul><h2 id="android-09-11-2026" tabindex="-1">Android (09/11/2026) <a class="header-anchor" href="#android-09-11-2026" aria-label="Permalink to &quot;Android (09/11/2026)&quot;">​</a></h2><p>Émulateurs du projet, APK debug construit depuis <code>main</code> du 09/11, même commerce. Données rejouées par <code>seed-stock-caisse.py</code> avec un fichier de secrets où <code>transferId</code> / <code>purchaseOrderId</code> étaient retirés (ceux du 08/11 avaient été reçus sur l&#39;iPad) : nouveau transfert <strong>TR-2026-0002</strong> et nouveau bon <strong>PO-EPI-2026-0004</strong>. Réception fournisseur et alertes sur la <strong>tablette</strong> (<code>emulator-5554</code>) ; transfert sur le <strong>téléphone</strong> (<code>emulator-5556</code>, voir plus bas pourquoi). Scénarios : <code>help/tools/mobile/scenarios/appareil-caisse-{reception-sur-la-caisse,recevoir-un-transfert,alertes-responsable}-android.json</code>.</p><table tabindex="0"><thead><tr><th>Capture</th><th>Ce qu&#39;elle montre</th></tr></thead><tbody><tr><td><img src="'+p+'" alt=""></td><td>Tablette : Réceptions fournisseur, PO-EPI-2026-0004 « Envoyé · 4 ligne(s) attendue(s) » (deux anciens bons en « Reçu en partie » dessous)</td></tr><tr><td><img src="'+m+'" alt=""></td><td>Tablette : <strong>Tout reçu</strong>, puis cidre ramené à 4 sur 6 → écart « Manquant » ; <strong>Valider la réception</strong></td></tr><tr><td><img src="'+g+'" alt=""></td><td>Tablette : « Réception de PO-EPI-2026-0004 enregistrée : stock à jour, 1 écart(s) signalé(s) — reliquat attendu »</td></tr><tr><td><img src="'+f+'" alt=""></td><td>Téléphone : TR-2026-0002 des Halles, 3 produits, 28 unités (identifiant de l&#39;expéditeur flouté)</td></tr><tr><td><img src="'+h+'" alt=""></td><td>Téléphone : <strong>Tout conforme</strong> puis beurre 5 sur 6 (« Manque 1 »), motif « Casse », PIN du responsable (masqué)</td></tr><tr><td><img src="'+b+'" alt=""></td><td>Téléphone : « Transfert TR-2026-0002 reçu : stock du magasin à jour, 1 écart(s) motivé(s) »</td></tr><tr><td><img src="'+v+'" alt=""></td><td>Tablette : Alertes — chiffres du jour, « Transfert à réceptionner » TR-2026-0002, deux « Stock bas »</td></tr></tbody></table><p>Corrigé pendant la séance : les écrans Android <strong>Transferts à recevoir</strong> et <strong>Alertes</strong> avaient un retour « ‹ Retour » écrit en dur en français (jamais traduit en anglais / arabe) au lieu de la flèche traduite des autres écrans ; remplacé par la flèche <code>caisse.goBack</code> (miroir en arabe), comme <strong>Réceptions fournisseur</strong>.</p><p>Incident de la séance : le serveur de dev (<code>:8080</code>, lancé à 23:56) a perdu ses classes partagées à 02:19 (le <code>shared-jvm.jar</code> du dépôt principal a été reconstruit sous lui) → <code>NoClassDefFoundError</code> (<code>DiscrepancyTypes</code>, <code>DeviceTransferLine</code>, <code>LowStockReachedPayload</code>) sur <code>GET /api/v1/pos/transfers</code> et sur le push des réceptions. Le transfert a donc été reçu par le téléphone appairé à un serveur lancé depuis le worktree de l&#39;agent sur <code>:8081</code> (même base de dev, arrêté ensuite). La réception fournisseur de la tablette (6 opérations) reste <strong>en attente d&#39;envoi</strong> jusqu&#39;au redémarrage du serveur de dev.</p><h2 id="reste" tabindex="-1">Reste <a class="header-anchor" href="#reste" aria-label="Permalink to &quot;Reste&quot;">​</a></h2><ul><li>Téléphone de salle : l&#39;icône <strong>Alertes</strong> du plan de salle n&#39;est pas capturée (alertes vues sur la caisse).</li></ul></div>',3)])])}const x=r(_,[["render",k]]);export{C as __pageData,x as default};
